// Generated by scripts/sync-arbiter-mod-vendor.mjs from clients/arbiter-core/src/contract/types.ts. Do not edit. Run the script.
// Canonical Arbiter wire contract — the single source of truth referenced by §4.4 of
// docs/plans/arbiter-agent-policy-hooks.md.
//
// STOPGAP: these belong in the shared `@langguard/policy-contract` package owned by the
// policy-engine-service-extraction. That package does not exist yet, so Arbiter defines
// them locally for PR0/PR1. When the extraction lands the package, migrate these verbatim
// and have the package re-export `ApprovalStatus` (shared/types/approval.ts) and
// `InterceptorViolation` (server/services/interceptor/types.ts) from their canonical homes.
// Laptop-side code must NOT deep-import `server/` or `shared/` (plan F6) — hence the mirrors below.

/** The Arbiter verdict triple. Never `defer` — the Claude Code adapter maps ASK→"ask". */
export type Verdict = 'ALLOW' | 'BLOCK' | 'ASK';

export type RiskTier = 'low' | 'medium' | 'high' | 'critical';

/** Mirror of shared/types/approval.ts ApprovalStatus. */
export type ApprovalStatus = 'approved' | 'not_approved' | 'banned';

/** Mirror of server/services/interceptor/types.ts InterceptorViolation. Do NOT widen. */
export interface InterceptorViolation {
  policy_id: string;
  status: 'notify' | 'block';
  details: string;
}

/** Which harness seam produced the request. */
export type HookPhase = 'enforce' | 'evidence' | 'verify';

/**
 * The four data-flow moments a policy may declare it inspects.
 *
 * MIRROR of `Checkpoint` in shared/policy-scope.ts, which is the frozen source
 * of truth. arbiter-core is the leaf of the dependency DAG and must not import
 * from `shared/` (plan F6), so this is a deliberate copy in the same style as
 * `ApprovalStatus` / `InterceptorViolation` above. Do NOT widen it here — a new
 * token is a spec amendment plus a row in both frozen availability tables.
 */
export type Checkpoint =
  | 'model_input'
  | 'model_output'
  | 'tool_call_input'
  | 'tool_call_output';

/**
 * Harness seam -> the checkpoint that seam's leg inspects.
 *
 * This is THE hook-phase mapping, extended one column; there is deliberately no
 * parallel per-harness table. Every adapter (claude / codex / cursor / shell /
 * antigravity) already funnels its hook event into one of these seam names
 * before calling runGate, so stamping here covers all of them at once and a new
 * harness inherits it for free.
 *
 *   screen   <- UserPromptSubmit  -> model_input
 *   enforce  <- PreToolUse        -> tool_call_input
 *   evidence <- PostToolUse       -> tool_call_output
 *   verify   <- Stop / SubagentStop -> model_output   (turn granularity; the
 *                                     frozen ruling is that Stop IS model_output,
 *                                     not a fifth checkpoint)
 *
 * `screen` is listed for completeness and is currently UNUSED on the decision
 * path: the SessionStart/UserPromptSubmit handler is advisory (it injects
 * context and never asks for a verdict), so nothing calls this with 'screen'
 * yet. It is recorded here rather than omitted so that whoever wires an
 * evaluating model_input leg finds the mapping already frozen instead of
 * minting a second one.
 *
 * Keyed as a plain string record so both `HookPhase` and the daemon's wider
 * `HookEvent` resolve against it without a cross-module type import (contract/
 * must not depend on daemon/).
 */
export const HOOK_PHASE_CHECKPOINT: Readonly<Record<string, Checkpoint>> = Object.freeze({
  screen: 'model_input',
  enforce: 'tool_call_input',
  evidence: 'tool_call_output',
  verify: 'model_output',
});

/**
 * The checkpoint for a harness seam, or `undefined` when the seam is unknown.
 *
 * UNDEFINED MEANS "DO NOT STAMP", never "stamp something plausible". An unknown
 * seam leaves the wire field absent, and an absent field is exactly the
 * no-signal case helpers.rego reads as ALL FOUR CHECKPOINTS IN PLAY — the
 * fail-safe direction. Guessing a token here would narrow enforcement to one
 * leg based on a string this build does not recognise.
 *
 * Own-property read: `phase` reaches this from a hook body and
 * `HOOK_PHASE_CHECKPOINT['constructor']` must never resolve to a function.
 */
export function checkpointForHookPhase(phase: string | undefined): Checkpoint | undefined {
  if (typeof phase !== 'string') return undefined;
  if (!Object.prototype.hasOwnProperty.call(HOOK_PHASE_CHECKPOINT, phase)) return undefined;
  return HOOK_PHASE_CHECKPOINT[phase];
}

// ── SCREEN (PIP) — POST /api/arbiter/context ──────────────────────────────
export interface ContextRequest {
  session_id: string;
  /** tools the harness reports as connected this session, when it exposes them (optional). */
  session_tools?: string[];
  caller_identity?: string;
}

export interface ContextResult {
  bundle_revision: string;
  /** tools that BLOCK if used (bounded — never the full catalog). */
  banned: string[];
  /** not_approved + SCOPE high/critical — these ASK. */
  requires_ask: string[];
  posture: {
    compliance_regimes: string[];
    enforce_not_approved: boolean;
    scope_default_tier: RiskTier;
  };
  /** ≤5 human-readable active-policy summaries, rendered into `additionalContext`. */
  guardrails: string[];
}

// ── ENFORCE / EVIDENCE / VERIFY (PDP) — POST /api/arbiter/verdict ──────────

/**
 * Capability labels emitted when recording an action (PR6, sequence policies).
 * Derived from SCOPE tier / tool category at the record site in each adapter.
 * Used by sequence_policies.rego to detect the lethal-trifecta chain.
 */
export type ActionCapability =
  | 'private_data_read'  // reads credential / secret / sensitive file paths
  | 'untrusted_input'    // receives data from external / user / network sources
  | 'external_send'      // sends data outbound (network, email, webhook)
  | 'write';             // modifies state (file, DB, API mutate)

export interface SessionAction {
  /** normalized dotted tool name, e.g. "github.create_pull_request". */
  tool: string;
  phase: HookPhase;
  verdict: Verdict;
  /** ISO-8601 timestamp. */
  ts: string;
  /**
   * Action category (PR6 — sequence detection).
   * Additive: existing callers that don't set it get undefined (rego-safe via object.get).
   * Examples: "read", "write", "approve", "deploy", "network_outbound", "package_install".
   */
  category?: string;
  /**
   * Capability labels for sequence detection (PR6).
   * Populated from SCOPE classification / shell action_type at the record site.
   * Additive: existing callers leave this undefined.
   */
  capabilities?: ActionCapability[];
}

/**
 * Derive category and capability labels for a SessionAction from the tool name
 * and optional shell action_type (from shell_action.rego).
 *
 * Client-side helper: uses tool name heuristics only (no SCOPE tier lookup,
 * since the daemon does not have SCOPE on the local native record path).
 * The server-side deriveActionMetadata in arbiter-service.ts also incorporates
 * the SCOPE tier for higher-fidelity derivation.
 *
 * Pure function — safe to call at record time with zero I/O.
 */
export function deriveSessionActionMetadata(
  tool: string,
  shellActionType?: string,
): { category: string; capabilities: ActionCapability[] } {
  const lower = tool.toLowerCase();

  // Shell action_type from the rego classifier (arbiter-shell path).
  if (shellActionType) {
    switch (shellActionType) {
      case 'catastrophic':       return { category: 'privileged_write', capabilities: ['write'] };
      case 'filesystem_delete':  return { category: 'write', capabilities: ['write'] };
      case 'git_history_rewrite': return { category: 'privileged_write', capabilities: ['write'] };
      case 'network_outbound':   return { category: 'write', capabilities: ['external_send', 'untrusted_input'] };
      case 'package_install':    return { category: 'write', capabilities: ['write'] };
      case 'credential_access':  return { category: 'read', capabilities: ['private_data_read'] };
      case 'safe_read':          return { category: 'read', capabilities: [] };
      default:                   break;
    }
  }

  // Heuristic derivation from tool name (applies to MCP tools and unknown shell).
  const mutationVerbs = ['create', 'update', 'delete', 'modify', 'write', 'send', 'push', 'deploy', 'approve', 'remove', 'publish', 'post', 'patch'];
  const isMutating = mutationVerbs.some((v) => lower.includes(v));
  const externalVerbs = ['send', 'publish', 'post', 'email', 'webhook', 'notify', 'broadcast'];
  const isExternal = externalVerbs.some((v) => lower.includes(v));
  const privateReadTerms = ['secret', 'credential', 'token', 'key', 'password', 'private', 'sensitive'];
  const isPrivateRead = privateReadTerms.some((v) => lower.includes(v));

  let category: string;
  if (lower.includes('approve') || lower.includes('review')) {
    category = 'approve';
  } else if (isMutating) {
    category = 'write';
  } else {
    category = 'read';
  }

  const capabilities: ActionCapability[] = [];
  if (isPrivateRead) capabilities.push('private_data_read');
  if (isExternal)    capabilities.push('external_send');
  if (isMutating)    capabilities.push('write');

  return { category, capabilities };
}

/**
 * Tool content carried to the remote engine, pre-truncated to the tenant's scan
 * window. Both fields are optional and phase-shaped: `args` is what the agent is
 * about to do (enforce), `output` is what came back (evidence).
 *
 * The server maps these onto the synthetic trace's TOOL observation —
 * args → observation_input, output → observation_output — which is exactly
 * where detectPii and the plugin engines look.
 */
export interface VerdictContent {
  /** Stringified tool arguments (enforce). Truncated to the scan window. */
  args?: string;
  /** Stringified tool response (evidence). Truncated to the scan window. */
  output?: string;
}

export interface VerdictRequest {
  session_id: string;
  /** normalized dotted tool name — a SINGLE string, never a candidate array (plan F1/F2). */
  tool: string;
  /**
   * Optional RAW (un-normalized, un-prefixed) tool name for exact server-side
   * entity-approval resolution. The ext_proc gate adapter sends a synthetic
   * `<platform>.<name>` `tool` (so the gate's native-tool check doesn't auto-allow a
   * dotless name) while the catalog entity is `<name>`; the server resolves approval
   * on `raw_tool ?? tool`.
   */
  raw_tool?: string;
  phase: HookPhase;
  /**
   * The checkpoint this leg inspects, derived from `phase` via
   * `checkpointForHookPhase`. The server stamps it onto the OPA input as
   * `input.phase`, where helpers.rego's `applies_to_phases` intersects it with
   * each policy's declared checkpoint set.
   *
   * NAMED `checkpoint`, NOT `phase`, ON PURPOSE: the wire already carries
   * `phase` meaning the harness seam ('enforce' | 'evidence' | 'verify'), and
   * two different vocabularies under one key is how a filter starts matching
   * the wrong thing. The rename to `input.phase` happens once, server-side,
   * where the Rego contract is spoken.
   *
   * OPTIONAL AND ADDITIVE. A daemon built before this field sends nothing, the
   * server stamps no phase, and helpers.rego reads that as all four checkpoints
   * in play — the older laptop keeps evaluating exactly what it evaluated
   * before rather than silently falling out of every per-leg policy.
   */
  checkpoint?: Checkpoint;
  /** sha256(stable-stringify(args)); used for the local verdict cache key. */
  args_hash?: string;
  /**
   * Tool content for the trace-dependent policy classes — PII, credential
   * surface, and the non-OPA engines (forge-bridge / typescript), none of which
   * the local bundle reproduces and none of which can decide anything from a
   * tool NAME alone.
   *
   * Both fields are already truncated to the tenant's configured scan window
   * (data.langguard.settings.pii_scan_max_chars) BEFORE they go on the wire —
   * there is no point shipping bytes the server will not scan.
   *
   * This deliberately reverses `plan F5` ("raw tool output never leaves the
   * laptop"), which assumed the remote engine was someone else's. It is not:
   * the arbiter service runs in the customer's own cloud, so this hop stays
   * inside their trust boundary. The old design's cost was a duplicate local
   * PII detector that silently drifted and was never even wired up (see
   * docs/plans/arbiter-tiered-evaluation.md).
   *
   * Kept in lockstep with the server's ArbiterVerdictRequest.
   */
  content?: VerdictContent;
  /** last ≤50 actions this session, for sequence-aware decisions (Phase 6). */
  session_actions?: SessionAction[];
  local_bundle_revision?: string;
  // ── Identity enrichment (optional additive — keeps lockstep with the server's
  // ArbiterVerdictRequest in server/services/arbiter/arbiter-types.ts). These let the
  // server enrich the synthetic arbiter trace so trace-completeness guardrails can pass.
  /**
   * Stable per-install id (Arbiter Management). Sent by the owner daemon so the
   * server can attribute per-device traffic counters and bump last_seen. Never
   * used for auth (tenant comes from the lgr_ key).
   */
  install_id?: string;
  /** Daemon build version (Arbiter Management), additive. */
  daemon_version?: string;
  /** Harness literal: 'claude' | 'cursor' | 'codex' | 'shell' (server re-validates the set). */
  agent_name?: string;
  /** Resolved once at daemon startup (env → git → os → 'unknown'). */
  user_id?: string;
  /** Registered app id, or `${harness}:${sessionId}` derived locally. */
  ai_app_id?: string;
  /** Optional org attribution. */
  department?: string;
  /** Optional deployment label. */
  environment?: string;
}

export interface VerdictResult {
  verdict: Verdict;
  /** present for BLOCK/ASK; absent for ALLOW. */
  reason?: string;
  /** EVIDENCE/VERIFY hard-violation flag (maps to Claude Code `decision:"block"`). */
  block?: boolean;
  violations: InterceptorViolation[];
  bundle_revision: string;
  evaluated: 'local' | 'remote';
}

// ── HEARTBEAT — POST /api/arbiter/heartbeat (Arbiter Management) ────────────
//
// Mirrors ArbiterHeartbeatRequest/Response in server/services/arbiter/arbiter-types.ts.
// Only the OWNER daemon sends this (standbys do not). The response carries any
// pending remote-control commands for this install (the command-poll piggyback).

/** Remote-control command vocabulary — matches shared/arbiter-management.ts COMMAND_TYPES. */
export type CommandType = 'set_enforcement_mode' | 'refresh_bundle' | 'revoke_self';

/** Daemon-reported ack outcome — matches shared/arbiter-management.ts ACK_OUTCOMES. */
export type AckOutcome = 'applied' | 'ignored' | 'failed';

/**
 * owner_harness value every SERVICE process reports: the hosted sidecar and the
 * ext_proc / http-authz container. It tells Arbiter Management the row is ONE
 * long-lived container process, not a developer machine, so the device list stays
 * a list of laptops. The server accepts it (server/routes/arbiter.ts `validAgents`)
 * and stores it, and it is NOT a developer harness, so it grows no harness children.
 *
 * A laptop daemon and the CLI keep reporting their real harness ('claude', ...).
 */
export const SERVICE_OWNER_HARNESS = 'gateway';

export interface ActiveHarness {
  harness: string;
  plugin_version?: string;
  ask_capable: boolean;
  sessions: number;
  last_active_at?: string;
}

export interface HeartbeatRequest {
  install_id: string;
  daemon_version: string;
  hostname?: string;
  platform?: string;
  arch?: string;
  owner_harness?: string;
  enforcement_mode: 'cooperative' | 'strict';
  bundle_revision?: string;
  pid?: number;
  active_harnesses: ActiveHarness[];
  /**
   * Local enforcement decisions per UTC hour and door (usage metering). Sent at most once
   * per hour and on shutdown; absent otherwise. `hour` is the ISO 8601 hour start.
   */
  usage?: Array<{ hour: string; door: 'hooks' | 'gateway_mcp'; count: number }>;
}

export interface PendingCommand {
  id: string;
  type: CommandType;
  payload?: { mode?: 'cooperative' | 'strict' };
}

export interface HeartbeatResponse {
  ok: true;
  commands: PendingCommand[];
}

export interface CommandAckRequest {
  install_id: string;
  outcome: AckOutcome;
  detail?: string;
}
